commands.command:
sudo tee /etc/nginx/conf.d/https8443.conf > /dev/null <<'EOF'
server {
    listen 8443 ssl;
    server_name node1;

    ssl_certificate     /etc/nginx/certs/cert.crt;
    ssl_certificate_key /etc/nginx/certs/cert.key;
    ssl_protocols TLSv1.2 TLSv1.3;

    location / {
        return 200 "ok\n";
        add_header Content-Type text/plain;
    }
}
EOF
sudo cat /etc/nginx/conf.d/https8443.conf

